/**
 * Returns models available to the authenticated user based on their group, token limits, and model ratios. Response format varies by modelType (OpenAI, Anthropic, or Gemini).
 * @summary List available models for the current user
 */
export type getV1ModelsResponse200 = {
  data: DtoApiResponse;
  status: 200;
};

export type getV1ModelsResponseSuccess = getV1ModelsResponse200 & {
  headers: Headers;
};
export type getV1ModelsResponse = getV1ModelsResponseSuccess;

export const getGetV1ModelsUrl = (params?: GetV1ModelsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/v1/models?${stringifiedParams}`
    : `/v1/models`;
};

export const getV1Models = async (
  params?: GetV1ModelsParams,
  options?: RequestInit,
): Promise<getV1ModelsResponse> => {
  return fetcher<getV1ModelsResponse>(getGetV1ModelsUrl(params), {
    ...options,
    method: "GET",
  });
};

